#include <iostream>
#include <cmath>
using namespace std;

int main() {

    // built-in function
    double result = sqrt(25.0);
    cout << "Square Root: " << result << endl;
    return 0;
}

#include <iostream>
using namespace std;

void greet() {
    cout << "Hello, World!" << endl;
}

int main() {
    greet();  // calling user-defined function
    return 0;
}

